// The city's texts (city.js) in Irish, as the sentences take them. Irish mutates nouns after the article and in the
// genitive, so the slots were made to take the nominative (foreign names unmutated): server after a colon ("Níl an
// freastalaí ag freagairt: {server}."), dataName first in "{name}: gan freagra faoi láthair" and alone in the map's
// popups, dataShort after "as" (no mutation: "sonraí as {data}"), techMap first in "{map} á lódáil…".
const own = (name, of, map, data, parking, credit) => ({
  server: of, dataName: map, dataShort: `${data} agus OSM`, techMap: map,
  parkingSource: parking, rulesHead: `Leithid mar atá i lámhleabhar IPR Phrág (C.2), mar threoir do ${name}:`, credit,
});
